define(["jquery"],function($){"use strict";return{init:function(ctx,cfg){if(!cfg){return}if(!ctx||!ctx.api||typeof ctx.api.registerGatekeeper!=="function"){return}let $container=$("#kopere-proctoring-overlay");if($container.length===0){return}let $footer=$container.find(".kopere-proctoring-footer");let $checkbox=$container.find('[data-role="contract-accept"]');let $error=$container.find('[data-role="contract-error"]');let accepted=$checkbox.is(":checked");ctx.api.registerRequirement("contract",{label:M.util.get_string("requirement_label","proctoringpolicy_contract"),satisfied:accepted});updatePendingState($footer,$checkbox,$error,accepted);$checkbox.on("change",function(){accepted=$(this).is(":checked");ctx.api.updateRequirement("contract",{satisfied:accepted});updatePendingState($footer,$checkbox,$error,accepted)});ctx.api.registerGatekeeper(function(){if(accepted){return true}$error.show();updatePendingState($footer,$checkbox,$error,accepted);$checkbox.trigger("focus");return false})}}});